<?php
namespace App\Http\Controllers;
use App\Models\Lead;use App\Models\Campaign;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class LeadController extends Controller {
private function rules($id=null){return ['first_name'=>'required|string|max:100','last_name'=>'nullable|string|max:100','company'=>'nullable|string|max:180','job_title'=>'nullable|string|max:180','email'=>['nullable','email','max:190',Rule::unique('leads','email')->ignore($id)],'phone'=>'nullable|string|max:40','linkedin_url'=>'nullable|url|max:500','website'=>'nullable|url|max:500','industry'=>'nullable|string|max:120','location'=>'nullable|string|max:180','source'=>'required|in:LinkedIn Sales Navigator,Website,Referral,Event,CSV Import,Other','status'=>'required|in:new,contacted,qualified,proposal,customer,lost','lead_score'=>'required|integer|min:0|max:100','notes'=>'nullable|string|max:5000','owner_id'=>'nullable|exists:users,id','campaign_id'=>'nullable|exists:campaigns,id'];}
public function index(Request $r){$q=Lead::with(['owner','campaign']);if($r->filled('q'))$q->where(fn($x)=>$x->where('first_name','like','%'.$r->q.'%')->orWhere('last_name','like','%'.$r->q.'%')->orWhere('company','like','%'.$r->q.'%')->orWhere('email','like','%'.$r->q.'%'));if($r->filled('status'))$q->where('status',$r->status);$leads=$q->latest()->paginate(12)->withQueryString();return view('leads.index',compact('leads'));}
public function create(){return view('leads.form',['lead'=>new Lead,'campaigns'=>Campaign::orderBy('name')->get(),'owners'=>User::orderBy('name')->get()]);}
public function store(Request $r){$d=$r->validate($this->rules());$d['owner_id']=$d['owner_id']??auth()->id();Lead::create($d);return redirect()->route('leads.index')->with('success','Lead created.');}
public function edit(Lead $lead){return view('leads.form',['lead'=>$lead,'campaigns'=>Campaign::orderBy('name')->get(),'owners'=>User::orderBy('name')->get()]);}
public function update(Request $r,Lead $lead){$d=$r->validate($this->rules($lead->id));$d['owner_id']=$d['owner_id']??auth()->id();$lead->update($d);return redirect()->route('leads.index')->with('success','Lead updated.');}
public function destroy(Lead $lead){$lead->delete();return back()->with('success','Lead deleted.');}
public function export(){return response()->streamDownload(function(){$o=fopen('php://output','w');fputcsv($o,['first_name','last_name','company','job_title','email','phone','linkedin_url','website','industry','location','source','status','lead_score','notes']);Lead::chunk(200,function($ls)use($o){foreach($ls as $l)fputcsv($o,[$l->first_name,$l->last_name,$l->company,$l->job_title,$l->email,$l->phone,$l->linkedin_url,$l->website,$l->industry,$l->location,$l->source,$l->status,$l->lead_score,$l->notes]);});fclose($o);},'pharmadem-leads.csv');}
public function import(Request $r){$r->validate(['csv'=>'required|file|mimes:csv,txt|max:5120']);$h=fopen($r->file('csv')->getRealPath(),'r');$head=fgetcsv($h);if(!$head){fclose($h);return back()->withErrors(['csv'=>'Empty CSV file.']);}$head=array_map(fn($v)=>strtolower(trim($v)),$head);$allowed=['first_name','last_name','company','job_title','email','phone','linkedin_url','website','industry','location','source','status','lead_score','notes'];$n=0;while(($row=fgetcsv($h))!==false){$d=array_combine($head,array_pad(array_slice($row,0,count($head)),count($head),null));$d=array_intersect_key($d,array_flip($allowed));if(empty($d['first_name']))continue;$d['source']=in_array($d['source']??'', ['LinkedIn Sales Navigator','Website','Referral','Event','CSV Import','Other'])?$d['source']:'CSV Import';$d['status']=in_array($d['status']??'', ['new','contacted','qualified','proposal','customer','lost'])?$d['status']:'new';$d['lead_score']=is_numeric($d['lead_score']??null)?min(100,max(0,(int)$d['lead_score'])):0;if(!empty($d['email']))Lead::updateOrCreate(['email'=>$d['email']],$d+['owner_id'=>auth()->id()]);else Lead::create($d+['owner_id'=>auth()->id()]);$n++;}fclose($h);return back()->with('success',"$n CSV rows imported.");}
}